import csv
import io


def parse_csv(raw_csv: str):
    expected_width = 8
    if raw_csv.startswith("\ufeff"):
        raw_csv = raw_csv[1:]

    records = csv.reader(
        io.StringIO(raw_csv, newline=""),
        delimiter=",",
        quotechar='"',
        doublequote=True,
    )

    # Find the populated header, skipping sparse preamble records.
    columns = []
    for record in records:
        if len(record) == expected_width and all(cell.strip() for cell in record):
            columns = record
            break

    if not columns:
        return {"columns": [], "rows": []}

    rows = list(records)
    width = max(len(columns), max((len(row) for row in rows), default=0))

    # Preserve surplus fields in additional columns instead of truncating them.
    used_names = {name.strip() for name in columns}
    suffix = 1
    while len(columns) < width:
        name = f"_extra_{suffix}"
        suffix += 1
        if name not in used_names:
            columns.append(name)
            used_names.add(name)

    for row in rows:
        row.extend([""] * (width - len(row)))

    return {"columns": columns, "rows": rows}
